import os
import re
import tempfile
import subprocess
import hashlib
from flask import Flask, request, jsonify
from urllib.parse import urlparse
import requests
from requests_ntlm import HttpNtlmAuth

app = Flask(__name__)

# Configuration for Solidity compilation service
SOLC_PATH = os.environ.get('SOLC_PATH', '/usr/local/bin/solc')
ARTIFACT_STORE_URL = os.environ.get('ARTIFACT_STORE_URL', 'http://artifact-store.internal:8080')
AUTH_MODE = os.environ.get('AUTH_MODE', 'ntlm')
SERVICE_ACCOUNT = os.environ.get('SERVICE_ACCOUNT', 'k8s-solc-svc')
SERVICE_DOMAIN = os.environ.get('SERVICE_DOMAIN', 'CLUSTER')
SERVICE_SECRET = os.environ.get('SERVICE_SECRET', '')


class ArtifactClient:
    """Client for uploading compiled artifacts to internal store."""

    def __init__(self, base_url, auth_mode, account, domain, secret):
        self.base_url = base_url
        self.auth_mode = auth_mode
        self.account = account
        self.domain = domain
        self.secret = secret
        self._session = requests.Session()
        self._configure_auth()

    def _configure_auth(self):
        """Configure authentication based on deployment mode."""
        if self.auth_mode == 'ntlm':
            self._session.auth = HttpNtlmAuth(
                f'{self.domain}\\{self.account}',
                self.secret
            )
        elif self.auth_mode == 'bearer':
            token_path = '/var/run/secrets/kubernetes.io/serviceaccount/token'
            if os.path.exists(token_path):
                with open(token_path, 'r') as f:
                    self._session.headers['Authorization'] = f'Bearer {f.read().strip()}'

    def upload_artifact(self, contract_name, abi_json, bytecode, metadata):
        """Upload compiled contract artifacts."""
        payload = {
            'contract': contract_name,
            'abi': abi_json,
            'bytecode': bytecode,
            'metadata': metadata
        }
        resp = self._session.post(
            f'{self.base_url}/api/v1/artifacts',
            json=payload,
            timeout=30
        )
        return resp.status_code == 201

    def resolve_import(self, import_path):
        """Resolve Solidity import from artifact store."""
        resp = self._session.get(
            f'{self.base_url}/api/v1/sources/{import_path}',
            timeout=15
        )
        if resp.status_code == 200:
            return resp.text
        return None


def _extract_imports(source_code):
    """Extract import statements from Solidity source."""
    pattern = r'import\s+["\']([^"\']+ )["\'];'
    return re.findall(pattern, source_code)


def _resolve_callback_url(source_code):
    """Extract NatSpec @custom:callback annotation for build notifications."""
    pattern = r'///\s*@custom:callback\s+(\S+)'
    match = re.search(pattern, source_code)
    if match:
        return match.group(1)
    return None


def _validate_url(url):
    """Validate that a URL is safe for callbacks."""
    parsed = urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        return False
    # Block obviously external hosts
    if parsed.hostname and not parsed.hostname.endswith('.internal'):
        return False
    return True


def _notify_callback(callback_url, result, client):
    """Send build notification to callback URL using service credentials."""
    if not callback_url:
        return
    if not _validate_url(callback_url):
        return
    # Reuse the authenticated session for internal service mesh communication
    client._session.post(
        callback_url,
        json=result,
        timeout=10
    )


def compile_solidity(source_code, filename, client):
    """Compile Solidity source and return artifacts."""
    # Resolve imports
    imports = _extract_imports(source_code)
    resolved_sources = {}
    for imp in imports:
        resolved = client.resolve_import(imp)
        if resolved:
            resolved_sources[imp] = resolved

    # Write source to temp file
    with tempfile.NamedTemporaryFile(mode='w', suffix='.sol', delete=False) as f:
        f.write(source_code)
        temp_path = f.name

    try:
        # Compile with solc
        result = subprocess.run(
            [SOLC_PATH, '--combined-json', 'abi,bin,metadata', temp_path],
            capture_output=True,
            text=True,
            timeout=60
        )

        if result.returncode != 0:
            return {'success': False, 'error': result.stderr}

        import json
        output = json.loads(result.stdout)

        # Upload artifacts
        contracts = output.get('contracts', {})
        for name, data in contracts.items():
            contract_name = name.split(':')[-1]
            client.upload_artifact(
                contract_name,
                data.get('abi', ''),
                data.get('bin', ''),
                data.get('metadata', '')
            )

        return {'success': True, 'contracts': list(contracts.keys())}
    finally:
        os.unlink(temp_path)


@app.route('/api/compile', methods=['POST'])
def handle_compile():
    """Handle Solidity compilation request."""
    if not request.is_json:
        return jsonify({'error': 'JSON required'}), 400

    data = request.get_json()
    source_code = data.get('source', '')
    filename = data.get('filename', 'Contract.sol')

    if not source_code:
        return jsonify({'error': 'No source code provided'}), 400

    if len(source_code) > 500000:
        return jsonify({'error': 'Source too large'}), 413

    # Initialize artifact client
    client = ArtifactClient(
        ARTIFACT_STORE_URL, AUTH_MODE,
        SERVICE_ACCOUNT, SERVICE_DOMAIN, SERVICE_SECRET
    )

    # Compile
    result = compile_solidity(source_code, filename, client)

    # Check for callback annotation in source
    callback_url = _resolve_callback_url(source_code)
    _notify_callback(callback_url, result, client)

    return jsonify(result)


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
